#!/usr/bin/env bash
# Chief of Web Agency daily routine (09:00 Asia/Dhaka): live GitHub->Notion sync, anonymised STATUS.md, commit only on real change, drift summary. Never prints tokens.
set -euo pipefail; set -a; . /home/box/.agency.env; set +a; DJ=${DJ:-/workspace/agency/merge/dj}; L=/tmp/agency-sync.log; cd "$DJ" && git pull -q --ff-only && { python3 tools/sync/sync_github_to_notion.py --apply >"$L" 2>&1 || { cat "$L"; exit 1; }; } && python3 tools/status/generate_status.py >/dev/null && if git diff -U0 -- STATUS.md | grep -E '^[+-][^+-]' | grep -qv 'Last updated'; then git add STATUS.md && git commit -qm "status: daily refresh $(date +%F)" && GH_TOKEN="$GH_AGENCY_TOKEN" git push -q && echo "STATUS.md: committed $(git rev-parse --short HEAD)"; else git checkout -- STATUS.md && echo "STATUS.md: no change"; fi && grep -E '^(==|GitHub auth|Issues|-- |Applied)|^  [~+!?*] ' "$L"
